function parseTitleAndChunk(title) {
	const match = title.match(/^(.*?)\s*\((Chunk\s+\d+\/\d+)\)$/i);
	return match ? {
		baseTitle: match[1].trim(),
		chunk: match[2].trim()
	} : {
		baseTitle: title.trim(),
		chunk: null
	};
}
